#!/usr/bin/env python3
"""Compute the import closure of AlgebraicJacobian.lean over modules on disk."""
import os, re, sys, json

P = "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
LIBDIR = os.path.join(P, "AlgebraicJacobian")
ROOTFILE = os.path.join(P, "AlgebraicJacobian.lean")

def mod_to_path(m):
    # m like AlgebraicJacobian.Picard.Foo
    parts = m.split(".")
    if parts[0] != "AlgebraicJacobian":
        return None
    if len(parts) == 1:
        return ROOTFILE
    return os.path.join(P, *parts) + ".lean"

def path_to_mod(p):
    rel = os.path.relpath(p, P)
    assert rel.endswith(".lean")
    return rel[:-5].replace(os.sep, ".")

# 1. all modules on disk
on_disk = {}
for dirpath, dirnames, filenames in os.walk(LIBDIR):
    for fn in filenames:
        if fn.endswith(".lean"):
            full = os.path.join(dirpath, fn)
            on_disk[path_to_mod(full)] = full
# also the root itself
on_disk_root = path_to_mod(ROOTFILE)

IMPORT_RE = re.compile(r'^\s*import\s+([A-Za-z0-9_.À-￿]+)', re.M)

def imports_of(path):
    try:
        with open(path, encoding="utf-8") as f:
            src = f.read()
    except OSError:
        return []
    # only the header: stop at first non-import, non-comment, non-blank line? simpler: scan all lines
    out = []
    for line in src.split("\n"):
        s = line.strip()
        if s.startswith("import "):
            out.append(s.split()[1])
        elif s.startswith("--") or s.startswith("/-") or s == "" or s.startswith("-/") or s.startswith("*") or s.startswith("set_option") or s.startswith("open "):
            continue
        else:
            break
    return out

# 2. BFS from root
seen = set()
stack = [(on_disk_root, ROOTFILE)]
edges = {}   # module -> list of AJ modules it imports
missing = []
while stack:
    m, p = stack.pop()
    if m in seen: continue
    seen.add(m)
    ims = [i for i in imports_of(p) if i == "AlgebraicJacobian" or i.startswith("AlgebraicJacobian.")]
    edges[m] = ims
    for i in ims:
        if i in seen: continue
        ip = mod_to_path(i)
        if ip and os.path.exists(ip):
            stack.append((i, ip))
        else:
            missing.append((m, i))

reachable = set(seen)
reachable.discard(on_disk_root)
all_mods = set(on_disk.keys())
unrooted = sorted(all_mods - reachable)

def lines(m):
    try:
        with open(on_disk[m], encoding="utf-8") as f:
            return sum(1 for _ in f)
    except OSError:
        return 0

print("modules on disk (excl. root aggregator):", len(all_mods))
print("reachable from root (excl. root):      ", len(reachable & all_mods))
print("reachable set size (incl. root):       ", len(seen))
print("UNROOTED:                              ", len(unrooted))
print("UNROOTED lines:                        ", sum(lines(m) for m in unrooted))
if missing:
    print("MISSING import targets:", missing)
print()
for m in unrooted:
    print(f"{lines(m):6d}  {m}")

json.dump({"unrooted": unrooted, "reachable": sorted(reachable & all_mods),
           "lines": {m: lines(m) for m in unrooted},
           "paths": on_disk},
          open("/tmp/reach.json","w"), indent=1)

